[tool_use bash_command] cat > /app/hierarchical_model.stan << 'EOF'
data {
  int<lower=0> N;           // number of observations
  array[N] int<lower=0> y;  // successes
  array[N] int<lower=0> n;  // trials
}

parameters {
  real<lower=0> alpha;
  real<lower=0> beta;
  vector<lower=0, upper=1>[N] theta;
}

model {
  // Prior: p(alpha, beta) proportional to (alpha + beta)^(-5/2)
  target += -2.5 * log(alpha + beta);

  // Hierarchical prior: theta_i ~ Beta(alpha, beta)
  theta ~ beta(alpha, beta);

  // Likelihood: y_i ~ Binomial(n_i, theta_i)
  y ~ binomial(n, theta);
}
EOF

[tool_use bash_command] cat /app/hierarchical_model.stan

